From 77e4e5762d19a9785c32c28b15b95c97ecd55969 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:54:56 +0100
Subject: [PATCH] applets/systemtray: Send SIGTERM to background apps before
 killing them

Apps without org.freedesktop.Application.quit were SIGKILLed right away
by flatpak kill, so Chrome lost its session. Now the app's main process
gets SIGTERM first and flatpak kill only runs if it's alive 10 s later.

BUG: 524863
---
 applets/systemtray/systemtraymodel.cpp | 73 +++++++++++++++++++++++---
 1 file changed, 67 insertions(+), 6 deletions(-)

diff --git a/applets/systemtray/systemtraymodel.cpp b/applets/systemtray/systemtraymodel.cpp
index 1f813729ac..dc77e3af23 100644
--- a/applets/systemtray/systemtraymodel.cpp
+++ b/applets/systemtray/systemtraymodel.cpp
@@ -24,10 +24,16 @@
 #include <Plasma/Applet>
 #include <PlasmaQuick/AppletQuickItem>

+#include <QFile>
 #include <QIcon>
+#include <QProcess>
 #include <QQuickItem>
+#include <QTimer>
+
+#include <signal.h>

 using namespace Qt::StringLiterals;
+using namespace std::chrono_literals;

 BaseModel::BaseModel(SystemTraySettings *settings, QObject *parent)
     : QAbstractListModel(parent)
@@ -549,6 +555,39 @@ void BackgroundAppsModel::openBackgroundApp(const QModelIndex &index)
     endRemoveRows();
 }

+static void killFlatpakInstance(const QString &instance)
+{
+    auto job = new KIO::CommandLauncherJob("flatpak"_L1, {"kill"_L1, instance});
+    auto delegate = new KNotificationJobUiDelegate(KJobUiDelegate::AutoErrorHandlingEnabled);
+    job->setUiDelegate(delegate);
+    job->start();
+}
+
+// The sandbox process reported by flatpak is bubblewrap's init, which ignores SIGTERM.
+// The app itself is the child that has pid 2 inside the sandbox.
+static pid_t sandboxedAppPid(pid_t sandboxPid)
+{
+    if (sandboxPid <= 0) {
+        return 0;
+    }
+    QFile children(u"/proc/%1/task/%1/children"_s.arg(sandboxPid));
+    if (!children.open(QIODevice::ReadOnly)) {
+        return 0;
+    }
+    for (const auto &child : children.readAll().split(' ')) {
+        QFile status(u"/proc/%1/status"_s.arg(QString::fromLatin1(child)));
+        if (child.isEmpty() || !status.open(QIODevice::ReadOnly)) {
+            continue;
+        }
+        for (const auto &line : status.readAll().split('\n')) {
+            if (line.startsWith("NSpid:") && line.split('\t').last() == "2") {
+                return child.toInt();
+            }
+        }
+    }
+    return 0;
+}
+
 void BackgroundAppsModel::stopBackgroundApp(const QModelIndex &index)
 {
     if (!checkIndex(index, CheckIndexOption::IndexIsValid)) {
@@ -569,12 +608,34 @@ void BackgroundAppsModel::stopBackgroundApp(const QModelIndex &index)
         watcher->deleteLater();
         if (watcher->isError()) {
             qCInfo(SYSTEM_TRAY) << "Failed to terminate background app via dbus:" << watcher->error();
-            for (const auto &instance : std::as_const(instances)) {
-                auto job = new KIO::CommandLauncherJob("flatpak"_L1, {"kill"_L1, instance});
-                auto delegate = new KNotificationJobUiDelegate(KJobUiDelegate::AutoErrorHandlingEnabled);
-                job->setUiDelegate(delegate);
-                job->start();
-            }
+            // flatpak kill sends SIGKILL, so first ask the app to quit with SIGTERM and only kill it if it doesn't
+            auto ps = new QProcess;
+            connect(ps, &QProcess::errorOccurred, ps, &QObject::deleteLater);
+            connect(ps, &QProcess::finished, ps, [ps, instances] {
+                ps->deleteLater();
+                QHash<QString, pid_t> sandboxPids;
+                for (const auto &line : QString::fromLocal8Bit(ps->readAllStandardOutput()).split(u'\n', Qt::SkipEmptyParts)) {
+                    const auto columns = line.split(u'\t');
+                    if (columns.size() == 2) {
+                        sandboxPids.insert(columns[0].trimmed(), columns[1].trimmed().toInt());
+                    }
+                }
+                for (const auto &instance : std::as_const(instances)) {
+                    const pid_t sandboxPid = sandboxPids.value(instance);
+                    const pid_t appPid = sandboxedAppPid(sandboxPid);
+                    if (appPid <= 0 || kill(appPid, SIGTERM) != 0) {
+                        killFlatpakInstance(instance);
+                        continue;
+                    }
+                    QTimer::singleShot(10s, [instance, sandboxPid, appPid] {
+                        if (sandboxedAppPid(sandboxPid) == appPid) {
+                            qCInfo(SYSTEM_TRAY) << "Background app did not quit after SIGTERM, killing it" << instance;
+                            killFlatpakInstance(instance);
+                        }
+                    });
+                }
+            });
+            ps->start(u"flatpak"_s, {u"ps"_s, u"--columns=instance,child-pid"_s});
         }
     });
     // Remove it from the model immediately - if things didnt work it will appear on the next update
-- 
